#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int *h = (int *)malloc((size_t)n * sizeof(int));
    int *left = (int *)malloc((size_t)n * sizeof(int));
    int *right = (int *)malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) scanf("%d", &h[i]);

    left[0] = h[0];
    for (int i = 1; i < n; i++)
        left[i] = h[i] > left[i-1] ? h[i] : left[i-1];

    right[n-1] = h[n-1];
    for (int i = n-2; i >= 0; i--)
        right[i] = h[i] > right[i+1] ? h[i] : right[i+1];

    long long count = 0;
    for (int i = 0; i < n; i++) {
        int lvl = left[i] < right[i] ? left[i] : right[i];
        if (lvl > h[i]) count++;
    }

    printf("%lld\n", count);
    free(h); free(left); free(right);
    return 0;
}
